// Event loop order: main script, then microtasks, then loop phases.
const fs = require('fs');

console.log('1 sync: main script start');
process.nextTick(() => console.log('3 nextTick (tick queue first)'));
Promise.resolve().then(() => console.log('4 promise (microtask, after ticks)'));
console.log('2 sync: main script end');

// Inside an I/O callback we are in the poll phase, so the check
// phase (setImmediate) comes before the next timers phase.
fs.readFile(__filename, () => {
  console.log('--- inside readFile callback (poll phase) ---');
  setTimeout(() => console.log('8 setTimeout 0 (next lap, timers)'), 0);
  setImmediate(() => console.log('7 setImmediate (check phase, this lap)'));
  process.nextTick(() => console.log('5 nextTick after callback'));
  Promise.resolve().then(() => console.log('6 promise after callback'));
});

// Microtask ordering: nextTick queue is drained before the promise queue,
// and the promise queue is drained fully before the loop moves on.
const log = [];
const say = (s) => { log.push(s); console.log(s); };

setImmediate(() => say('G setImmediate'));
Promise.resolve().then(() => {
  say('C promise 1');
  // A tick scheduled from inside a microtask waits until the
  // microtask queue is empty, then runs before the loop continues.
  process.nextTick(() => say('F nextTick scheduled from a promise'));
  Promise.resolve().then(() => say('E promise 3 (nested, same drain)'));
});
Promise.resolve().then(() => say('D promise 2'));
queueMicrotask(() => say('D2 queueMicrotask (same queue as promises)'));
process.nextTick(() => say('B nextTick'));
say('A sync');
setImmediate(() => console.log('order:', log.map((s) => s[0]).join('')));

// Same CPU work, two ways. A "request" is queued right after the work starts.
// We print the order to see whether the request waits for all the work.
function work(a, b) { let s = 0; for (let i = a; i < b; i++) s += i % 7; return s; }

const TOTAL = 3000000, CHUNK = 1000000;

// 1) Blocking: one long synchronous loop.
setImmediate(() => console.log('blocking: request served AFTER all work'));
console.log('blocking: start, result', work(0, TOTAL));

// 2) Chunked: do a slice, then yield with setImmediate.
setTimeout(() => {
  let done = 0, sum = 0;
  function step() {
    sum += work(done, done + CHUNK);
    done += CHUNK;
    console.log('chunked: finished', done, 'of', TOTAL);
    if (done < TOTAL) setImmediate(step); // let other callbacks run in between
    else console.log('chunked: result', sum);
  }
  setImmediate(() => console.log('chunked: request served between chunks'));
  step();
}, 10);
// Cost: same total CPU, slightly more overhead; latency of others drops
// from the whole job to one chunk.

// Simulated libuv pool: fixed workers, a queue, and a virtual clock (ms).
// Not real threads: it shows how queueing delays a quick job (like a DNS lookup).
function simulate(poolSize, tasks) {
  const free = new Array(poolSize).fill(0); // time each worker becomes free
  const out = [];
  for (const t of tasks) {
    let w = 0;                                   // pick the worker free earliest
    for (let i = 1; i < poolSize; i++) if (free[i] < free[w]) w = i;
    const start = Math.max(free[w], t.arrive);
    free[w] = start + t.cost;
    out.push(t.name + ' waited ' + (start - t.arrive) + ' ms, done at ' + free[w]);
  }
  return out;
}

// 8 slow file reads (100 ms each) arrive at t=0, then a 5 ms DNS lookup at t=1.
const tasks = [];
for (let i = 1; i <= 8; i++) tasks.push({ name: 'read' + i, arrive: 0, cost: 100 });
tasks.push({ name: 'dns', arrive: 1, cost: 5 });

for (const size of [4, 8]) {
  console.log('--- pool size ' + size + ' ---');
  const lines = simulate(size, tasks);
  console.log(lines[0]);
  console.log(lines[lines.length - 1]);
}

// Backpressure: write() returns false once the buffer reaches highWaterMark.
const { Writable } = require('stream');

const slow = new Writable({
  highWaterMark: 10,                       // buffer limit in bytes
  write(chunk, enc, cb) { setTimeout(cb, 20); } // slow consumer: 20 ms per chunk
});

let i = 0;
function produce() {
  while (i < 6) {
    const ok = slow.write(Buffer.alloc(4)); // 4-byte chunks
    i++;
    console.log('wrote chunk', i, '-> write() returned', ok,
                '| buffered bytes:', slow.writableLength);
    if (!ok) {                              // stop, wait for the buffer to empty
      console.log('   producer pauses until drain');
      slow.once('drain', () => { console.log('   drain: resuming'); produce(); });
      return;
    }
  }
  slow.end(() => console.log('all chunks written'));
}
produce();
// Memory stays near highWaterMark instead of growing with the data size.

const EventEmitter = require('events');

// A tiny once(): wrap the listener so it removes itself before running.
function onceOf(em, name, fn) {
  function wrapper(...args) {
    em.off(name, wrapper);       // remove first, so it fires only once
    return fn.apply(this, args);
  }
  em.on(name, wrapper);
}

const em = new EventEmitter();
onceOf(em, 'hello', (n) => console.log('once listener got', n));
em.on('hello', (n) => console.log('normal listener got', n));
console.log('emit 1 ran listeners:', em.emit('hello', 1)); // both run
console.log('emit 2 ran listeners:', em.emit('hello', 2)); // only normal runs
console.log('listeners left:', em.listenerCount('hello'));

// Pitfall: 'error' with no listener throws.
try { em.emit('error', new Error('boom')); }
catch (e) { console.log('unhandled error event threw:', e.message); }

// Pitfall: a throwing listener stops the later ones.
const e2 = new EventEmitter();
e2.on('x', () => { throw new Error('first failed'); });
e2.on('x', () => console.log('second listener'));
try { e2.emit('x'); } catch (e) { console.log('emit threw:', e.message, '- second never ran'); }

// A mini Express: middleware list + compose. Error handlers have 4 params.
function createApp() {
  const stack = [];
  return {
    use(fn) { stack.push(fn); },
    handle(req, res) {
      let i = 0;
      function next(err) {
        const fn = stack[i++];
        if (!fn) return err ? res.push('500 ' + err.message) : res.push('404');
        const isErrorMw = fn.length === 4;
        try {
          if (err && isErrorMw) fn(err, req, res, next);   // error path
          else if (!err && !isErrorMw) fn(req, res, next); // normal path
          else next(err);                                  // skip mismatches
        } catch (e) { next(e); }                           // sync throw -> error path
      }
      next();
    }
  };
}

function run(path) {
  const app = createApp(), res = [];
  app.use((req, r, next) => { r.push('log ' + req.path); next(); });
  app.use((req, r, next) => req.path === '/bad' ? next(new Error('bad input')) : next());
  app.use((req, r, next) => { if (req.path === '/crash') throw new Error('bug'); next(); });
  app.use((req, r) => r.push('200 hello')); // ends: never calls next
  app.use((err, req, r, next) => { r.push('handled: ' + err.message); });
  app.handle({ path }, res);
  console.log(path.padEnd(7), '->', res.join(' | '));
}
['/ok', '/bad', '/crash'].forEach(run);
